contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint valBeforeInit, uint valAfterInit) public {
        require(true);

        c.Initialized(); if (__ESBMC_reverted()) return;

        bool revertedAfterInit;
        c.SetMinSum(valAfterInit); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            revertedAfterInit = true;
        } else {
            revertedAfterInit = false;
        }

        assert(revertedAfterInit);
    }
}

