pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 valBeforeInit, uint256 valAfterInit) internal {
        vm.assume(true);
        try c.Initialized() {} catch { return; }
        bool revertedAfterInit;
        try c.SetMinSum(valAfterInit) {
            revertedAfterInit = false;
        } catch {
            revertedAfterInit = true;
        }
        assertTrue(revertedAfterInit);
    }

    function testFuzz_run(uint256 valBeforeInit, uint256 valAfterInit) public {
        _run(valBeforeInit, valAfterInit);
    }

    receive() external payable {}
}
